{
  "query": "How do I compare net yield and projected IRR across the available units?",
  "summary": "Compare units on a common basis: calculate net yield (after all recurring costs and fees) for current income, then compare projected IRR using the same holding period, exit assumptions, and fee treatment. Projected IRR is more informative than yield alone because it includes appreciation, financing effects, fees, and exit timing.",
  "caveat": "I don't have verified details of Propbase's current listing fields, fee schedule, or projection methodology. Check each listing's disclosure documents for the exact inputs before relying on these numbers.",
  "step_by_step": [
    {
      "step": 1,
      "title": "Normalize to the same investment base",
      "detail": "Use your actual cash outlay per unit or per token, including purchase fees, platform fees, and closing costs. Compare per-dollar returns, not headline token prices, since fractional units can differ in minimum size and secondary-market pricing."
    },
    {
      "step": 2,
      "title": "Calculate gross yield",
      "formula": "Gross yield = Annualized gross rent / Total investment basis",
      "detail": "Use contracted or in-place rent where available, and annualize any partial-year figures."
    },
    {
      "step": 3,
      "title": "Calculate net yield",
      "formula": "Net yield = (Gross rent - vacancy allowance - property management - maintenance reserve - property taxes - insurance - HOA/operating costs - platform/servicing fees) / Total investment basis",
      "detail": "Apply the same vacancy and maintenance assumptions to every unit so differences reflect the properties, not the assumptions. Note whether the platform's stated yield is gross or net; many listings headline gross figures."
    },
    {
      "step": 4,
      "title": "Build a cash flow schedule for projected IRR",
      "detail": "For each unit, list: initial outflow (negative, including all fees) in year 0; annual net distributions in years 1 through N; exit proceeds in year N (estimated sale price minus selling costs, debt payoff if any, and your share of any remaining reserves). Then compute IRR (or XIRR if dates are irregular)."
    },
    {
      "step": 5,
      "title": "Hold the assumptions constant",
      "detail": "Use the same holding period, rent growth rate, expense inflation, vacancy rate, and exit cap rate for all units when comparing. Differences in IRR should come from the properties and fee structures, not from optimistic projections on one listing."
    },
    {
      "step": 6,
      "title": "Run sensitivity tests",
      "detail": "Recalculate IRR with lower exit prices (for example, -10% and -20%), higher vacancy, and a one-year-later exit. A unit whose IRR collapses under modest stress carries more risk than its base case implies."
    },
    {
      "step": 7,
      "title": "Adjust for liquidity and risk",
      "detail": "Tokenized real estate often has thin secondary markets. Factor in the expected time and discount needed to exit, the sponsor's track record, legal structure (SPV, token holder rights), and whether distributions are paid on-chain or off-chain."
    }
  ],
